{"content":"#!/usr/bin/env python3
"""
Command-line todo manager storing data in todos.json.
"""

import json
import sys
import os
from pathlib import Path


TODO_FILE = Path("todos.json")


def load_todos():
    """Load todos from JSON file. Returns empty list if file doesn't exist."""
    if not TODO_FILE.exists():
        return []
    try:
        with TODO_FILE.open("r") as f:
            data = json.load(f)
            # Ensure it's a list
            if isinstance(data, list):
                return data
            return []
    except (json.JSONDecodeError, OSError):
        return []


def save_todos(todos):
    """Save todos to JSON file."""
    with TODO_FILE.open("w") as f:
        json.dump(todos, f)


def get_next_id(todos):
    """Get the next available ID (max existing ID + 1, or 1 if empty)."""
    if not todos:
        return 1
    return max(todo["id"] for todo in todos) + 1


def find_todo(todos, todo_id):
    """Find a todo by ID. Returns (index, todo) or (None, None) if not found."""
    for i, todo in enumerate(todos):
        if todo["id"] == todo_id:
            return i, todo
    return None, None


def cmd_add(text):
    """Add a new todo."""
    todos = load_todos()
    todo_id = get_next_id(todos)
    todo = {"id": todo_id, "text": text, "done": False}
    todos.append(todo)
    save_todos(todos)
    print(f"Added #{todo_id}")


def cmd_list():
    """List all todos."""
    todos = load_todos()
    if not todos:
        print("No todos.")
        return
    for todo in sorted(todos, key=lambda t: t["id"]):
        status = "x" if todo["done"] else " "
        print(f"{todo['id']}. [{status}] {todo['text']}")


def cmd_done(todo_id):
    """Mark a todo as done."""
    todos = load_todos()
    index, todo = find_todo(todos, todo_id)
    if todo is None:
        print(f"Error: todo #{todo_id} not found", file=sys.stderr)
        sys.exit(1)
    todo["done"] = True
    save_todos(todos)
    print(f"Completed #{todo_id}")


def cmd_remove(todo_id):
    """Remove a todo."""
    todos = load_todos()
    index, todo = find_todo(todos, todo_id)
    if todo is None:
        print(f"Error: todo #{todo_id} not found", file=sys.stderr)
        sys.exit(1)
    todos.pop(index)
    save_todos(todos)
    print(f"Removed #{todo_id}")


def main():
    if len(sys.argv) < 2:
        print("Usage: python3 todo.py <command> [args...]", file=sys.stderr)
        print("Commands: add, list, done, remove", file=sys.stderr)
        sys.exit(1)

    command = sys.argv[1]

    if command == "add":
        if len(sys.argv) < 3:
            print("Usage: python3 todo.py add \"<text>\"", file=sys.stderr)
            sys.exit(1)
        # Join all remaining args as the text (in case text has spaces)
        text = " ".join(sys.argv[2:])
        cmd_add(text)
    elif command == "list":
        cmd_list()
    elif command == "done":
        if len(sys.argv) < 3:
            print("Usage: python3 todo.py done <id>", file=sys.stderr)
            sys.exit(1)
        try:
            todo_id = int(sys.argv[2])
        except ValueError:
            print("Error: id must be an integer", file=sys.stderr)
            sys.exit(1)
        cmd_done(todo_id)
    elif command == "remove":
        if len(sys.argv) < 3:
            print("Usage: python3 todo.py remove <id>", file=sys.stderr)
            sys.exit(1)
        try:
            todo_id = int(sys.argv[2])
        except ValueError:
            print("Error: id must be an integer", file=sys.stderr)
            sys.exit(1)
        cmd_remove(todo_id)
    else:
        print(f"Unknown command: {command}", file=sys.stderr)
        print("Commands: add, list, done, remove", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()","path":"todo.py"}
